head.script:
scwin.checkVal = function() {
	const left = (document.getElementById('tabControl1_btn_scrollLeft') || document.getElementById('mf_tabControl1_btn_scrollLeft')).getAttribute('tabindex');
	const submenu = (document.getElementById('tabControl1_btn_submenu') || document.getElementById('mf_tabControl1_btn_submenu')).getAttribute('tabindex');
	const right = (document.getElementById('tabControl1_btn_scrollRight') || document.getElementById('mf_tabControl1_btn_scrollRight')).getAttribute('tabindex');
	return left == null && submenu == null && right == null;
};
